class ReabrirLineaBody(BaseModel):
    pedido_id: str
    linea_huella: str
    reabierta_por_email: str = ""
    motivo: str = Field(default="", max_length=500)


@app.post("/api/logistica/reabrir-linea")
def reabrir_linea(
    req: ReabrirLineaBody,
    request: Request,
    x_api_key: Optional[str] = Header(default=None),
) -> dict[str, Any]:
    """Reabre una línea cerrada en campo: deja trazabilidad (nueva fila
    REABIERTA en cierres_linea) y avisa a la oficina."""
    _verify_key(x_api_key)
    _check_rate_limit(request.client.host if request.client else "unknown", POST_LIMIT)
    _ensure_cierres_table()
    client.query(
        f"INSERT INTO `{PROJECT}.{PICKING_DATASET}.{CIERRES_TABLE}` "
        f"(id, pedido_id, linea_huella, cantidad_faltante, motivo, motivo_texto, operario_email, operario_nombre, creado_en) "
        f"VALUES ({_esc(uuid.uuid4())}, {_esc(req.pedido_id)}, {_esc(req.linea_huella)}, 0, 'REABIERTA', "
        f"{_esc(req.motivo)}, {_esc(req.reabierta_por_email)}, '', CURRENT_TIMESTAMP())"
    ).result()
    pos = _posicion_linea(req.pedido_id, req.linea_huella)
    cuerpo = (
        f"↩️ Línea reabierta ({req.pedido_id}" +
        (f" · línea {pos}" if pos else "") + ")"
    )
    try:
        ofis = _query(
            f"SELECT email FROM `{PROJECT}.{PICKING_DATASET}.{ENCARGADOS_TABLE}` WHERE rol = 'SUPERUSUARIO'"
        )
        for ofi in ofis:
            _enviar_fcm(
                ofi["email"], "Línea reabierta", cuerpo[:300],
                {"tipo": "cierre_linea", "pedido": req.pedido_id, "linea": req.linea_huella},
            )
    except Exception:
        pass
    return {"ok": True}


